#include "KS/SRC/iri.h"

template<class RandomAccessIterator>
void make_heap(
    RandomAccessIterator first,
    RandomAccessIterator last);

template<
    class RandomAccessIterator,
    class T,
    class Distance>
void __pop_heap(
    RandomAccessIterator first,
    RandomAccessIterator last,
    RandomAccessIterator result,
    T value,
    Distance *);

template<class RandomAccessIterator>
void sort_heap(
    RandomAccessIterator first,
    RandomAccessIterator last);

template<class RandomAccessIterator, class T>
void __partial_sort(
    RandomAccessIterator first,
    RandomAccessIterator middle,
    RandomAccessIterator last,
    T *)
{
    make_heap(first, middle);
    for (RandomAccessIterator iterator = middle;
         iterator < last;
         ++iterator) {
        if (*iterator < *first) {
            __pop_heap(
                first,
                middle,
                iterator,
                T(*iterator),
                (int *)0);
        }
    }
    sort_heap(first, middle);
}

template void __partial_sort(
    instance_render_info *,
    instance_render_info *,
    instance_render_info *,
    instance_render_info *);
